// The printer list and the result lines an OrcaSlicer import shows: on the
// first launch's Printers step (Home page, canvas boards 07 and 17) and in
// File › Import › Import from OrcaSlicer… (this page, boards orca-import-02
// to 04). Both pages draw this one markup, with its own stylesheet, so the
// two cannot drift apart.

import './OrcaImportLists.css';

export interface OrcaPrinterRow {
  name: string;
  // JusPrin has it already, so the import skips it.
  already: boolean;
}

export interface OrcaImportResultLine {
  kind: 'printer' | 'filament' | 'process';
  name: string;
  renamedTo: string;
  imported: boolean;
  // Why it was not imported, as a sentence.
  reason: string;
}

// With `chosen` and `onChoose`, each printer JusPrin doesn't have yet has a
// tick box, and only the ticked ones are imported.
export function OrcaPrinterList({ printers, chosen, onChoose, disabled }: {
  printers: OrcaPrinterRow[];
  chosen?: string[];
  onChoose?: (name: string, ticked: boolean) => void;
  disabled?: boolean;
}) {
  return (
    <ul className="orca-import-list" aria-label="OrcaSlicer printers">
      {printers.map(({ name, already }, index) => (
        <li key={`${name}:${index}`} className={already ? 'orca-import-row orca-import-row--already' : 'orca-import-row'}>
          {!already && chosen && onChoose ? (
            <label className="orca-import-choice">
              <input type="checkbox" checked={chosen.includes(name)} disabled={disabled}
                onChange={(event) => onChoose(name, event.target.checked)} />
              <span className="orca-import-row-name">{name}</span>
            </label>
          ) : <>
            <span className={`orca-import-icon ${already ? 'orca-import-icon--check' : 'orca-import-icon--printer'}`} aria-hidden="true" />
            <span className="orca-import-row-name">{name}</span>
          </>}
          {already && <span className="orca-import-row-status">Already in JusPrin</span>}
        </li>
      ))}
    </ul>
  );
}

function status(line: OrcaImportResultLine) {
  if (!line.imported) return line.reason;
  return line.renamedTo ? `Imported as ‘${line.renamedTo}’` : 'Imported';
}

// Printers and processes a line each, the outcome under the name; filaments
// as a count with the names of those imported, and any not imported listed
// so each says why.
export function OrcaImportResultLines({ lines }: { lines: OrcaImportResultLine[] }) {
  const filaments = lines.filter((line) => line.kind === 'filament');
  const imported = filaments.filter((line) => line.imported).map((line) => line.renamedTo || line.name);
  const importedFilaments = imported.length;
  const listed = lines.filter((line) => line.kind !== 'filament' || !line.imported);
  const noun = filaments.length === 1 ? 'filament' : 'filaments';
  return <>
    {listed.length > 0 && (
      <ul className="orca-import-list" aria-label="Imported">
        {listed.map((line, index) => (
          <li key={`${line.kind}:${line.name}:${index}`} className="orca-import-row">
            <span className={`orca-import-icon ${line.imported ? 'orca-import-icon--done' : 'orca-import-icon--warning'}`}
              aria-hidden="true" />
            <span className="orca-import-line">
              <span className="orca-import-row-name">{line.name}</span>
              <span className="orca-import-row-status">{status(line)}</span>
            </span>
          </li>
        ))}
      </ul>
    )}
    {filaments.length > 0 && (
      <p className="orca-import-count">
        {importedFilaments === filaments.length
          ? `${filaments.length} ${noun} imported`
          : `${importedFilaments} of ${filaments.length} ${noun} imported`}
        {importedFilaments > 0 ? `: ${imported.join(', ')}.` : '.'}
      </p>
    )}
  </>;
}
  return <p className="onboarding-done"><CheckGlyph />{text}</p>;
}

// Importing holds the app on the action's message, so the button says so
// first and the message goes once that has been painted. The host answers
// every action with fresh state.
function useBusy(onAction: Action, onboarding: OnboardingState) {
  const [busy, setBusy] = useState(false);
  useEffect(() => setBusy(false), [onboarding]);
  const run = (type: string, payload?: object) => {
    setBusy(true);
    afterPaint(() => onAction(type, payload));
  };
  return [busy, run] as const;
}

// The printer JusPrin selects once the import is done, as the importer
// picks it: OrcaSlicer's own, while it is ticked, otherwise the first ticked.
function startsWith(orca: OnboardingState['orca'], chosen: string[]): string {
  const ticked = orca.printers.filter((name) => chosen.includes(name));
  if (ticked.length === 0) return '';
  if (ticked.includes(orca.selected)) return `JusPrin starts with ${orca.selected}, the printer OrcaSlicer had selected.`;
  return `JusPrin starts with ${ticked[0]}.`;
}

function OrcaImport({ onboarding, error, onAction }: Props) {
  const { orca } = onboarding;
  const [busy, run] = useBusy(onAction, onboarding);
  // Every printer starts ticked; only the ticked ones are imported.
  const [chosen, setChosen] = useState(orca.printers);
  const listed = orca.printers.join('\n');
  useEffect(() => setChosen(orca.printers), [listed]);
  const choose = (name: string, ticked: boolean) =>
    setChosen((now) => (ticked ? [...now, name] : now.filter((one) => one !== name)));
  const starts = startsWith(orca, chosen);
  return (
    <div className="onboarding-step">
      <WelcomeDone onboarding={onboarding} />
      <div className="onboarding-heading">
        <h1>Bring your printers from OrcaSlicer?</h1>
        <p className="onboarding-lead">
          JusPrin copies these printers with their filaments, settings and printer connections. OrcaSlicer keeps its own copy.
        </p>
      </div>
      <OrcaPrinterList printers={orca.printers.map((name) => ({ name, already: false }))} chosen={chosen} onChoose={choose}
        disabled={busy} />
      <div className="onboarding-source">
        {orca.filamentCount > 0 && (
          <p>Also brings {orca.filamentCount === 1 ? '1 filament' : `${orca.filamentCount} filaments`}.</p>
        )}
        <p className="onboarding-source-folder">
          <FolderGlyph />
          <span className="onboarding-source-path">{orca.source}</span>
        </p>
      </div>
      {starts && <p className="onboarding-lead">{starts}</p>}
      {error && <p className="onboarding-error" role="alert">{error}</p>}
      <div className="onboarding-actions">
        <button type="button" className="button-primary" disabled={busy || chosen.length === 0}
          onClick={() => run('onboarding_import', { printers: chosen })}>
          {busy ? 'Importing…' : 'Import'}
        </button>
        <button type="button" className="button-secondary" disabled={busy} onClick={() => onAction('onboarding_start_fresh')}>
          Choose my printer instead
        </button>
      </div>
      <button type="button" className="onboarding-link flush" disabled={busy} onClick={() => onAction('onboarding_back')}>Back</button>
    </div>
  );
}

// A line not imported says what to do about it, trying again included.
function ImportResult({ onboarding, error, onAction }: Props) {
  const items = onboarding.orca.importResult ?? [];
  return (
    <div className="onboarding-step">
      <div className="onboarding-heading">
        <h1>Imported from OrcaSlicer</h1>
      </div>
      <OrcaImportResultLines lines={items} />
      {error && <p className="onboarding-error" role="alert">{error}</p>}
      <div className="onboarding-actions">
        <button type="button" className="button-primary" onClick={() => onAction('onboarding_import_continue')}>
          Continue
        </button>
      </div>
    </div>
  );
}

// "Which printer do you have?": the printer and its nozzle, added with its
// profile's own plate and filament. The dialog Home's "+ Add printer" opens
